-- A Role card's Hard switch Change Project settings (spec §6), enforced by The Office: every stored
-- card version gets it by its Role's key, as the presets set it (Devops Allowed; Developer and CTO
-- Consult Devops; Planner, Reviewer, Office Manager and the Caretaker Never), a Role hired from
-- scratch Ask me. A card the release before saves after a rollback lacks it, which
-- `PostgresRoleRepository` reads as Ask me.
UPDATE "role_card_versions" SET "card" = jsonb_set("card", '{hardSwitches,changeProjectSettings}', CASE "role_key" WHEN 'devops' THEN '{"kind":"allowed"}'::jsonb WHEN 'developer' THEN '{"kind":"consult","role":"devops"}'::jsonb WHEN 'cto' THEN '{"kind":"consult","role":"devops"}'::jsonb WHEN 'planner' THEN '{"kind":"never"}'::jsonb WHEN 'reviewer' THEN '{"kind":"never"}'::jsonb WHEN 'office-manager' THEN '{"kind":"never"}'::jsonb WHEN 'caretaker' THEN '{"kind":"never"}'::jsonb ELSE '{"kind":"ask-me"}'::jsonb END) WHERE jsonb_typeof("card"->'hardSwitches') = 'object' AND NOT ("card"->'hardSwitches' ? 'changeProjectSettings');--> statement-breakpoint
-- A hire Proposal's card is a whole card of a Role hired from scratch, whatever its status: Ask me.
UPDATE "proposals" SET "change" = jsonb_set("change", '{card,hardSwitches,changeProjectSettings}', '{"kind":"ask-me"}'::jsonb) WHERE "change"->>'kind' = 'hire' AND jsonb_typeof("change"->'card'->'hardSwitches') = 'object' AND NOT ("change"->'card'->'hardSwitches' ? 'changeProjectSettings');--> statement-breakpoint
-- So is the card of each hire from scratch in an office-setup Proposal, whatever its status.
UPDATE "proposals" SET "change" = jsonb_set("change", '{hires}', (SELECT jsonb_agg(CASE WHEN "hire"->>'kind' = 'hire' AND jsonb_typeof("hire"->'card'->'hardSwitches') = 'object' AND NOT ("hire"->'card'->'hardSwitches' ? 'changeProjectSettings') THEN jsonb_set("hire", '{card,hardSwitches,changeProjectSettings}', '{"kind":"ask-me"}'::jsonb) ELSE "hire" END ORDER BY "position") FROM jsonb_array_elements("change"->'hires') WITH ORDINALITY AS "hires"("hire", "position"))) WHERE "change"->>'kind' = 'office-setup' AND EXISTS (SELECT 1 FROM jsonb_array_elements("change"->'hires') AS "hires"("hire") WHERE "hire"->>'kind' = 'hire' AND jsonb_typeof("hire"->'card'->'hardSwitches') = 'object' AND NOT ("hire"->'card'->'hardSwitches' ? 'changeProjectSettings'));--> statement-breakpoint
-- A change Proposal that rewrites the Hard switches, whatever its status, gives them whole in
-- `from` and `to`: each keeps the switch as the stored cards of its Role now have it.
UPDATE "proposals" SET "change" = jsonb_set("change", '{from,hardSwitches,changeProjectSettings}', CASE "change"->>'roleKey' WHEN 'devops' THEN '{"kind":"allowed"}'::jsonb WHEN 'developer' THEN '{"kind":"consult","role":"devops"}'::jsonb WHEN 'cto' THEN '{"kind":"consult","role":"devops"}'::jsonb WHEN 'planner' THEN '{"kind":"never"}'::jsonb WHEN 'reviewer' THEN '{"kind":"never"}'::jsonb WHEN 'office-manager' THEN '{"kind":"never"}'::jsonb WHEN 'caretaker' THEN '{"kind":"never"}'::jsonb ELSE '{"kind":"ask-me"}'::jsonb END) WHERE "change"->>'kind' = 'change' AND jsonb_typeof("change"->'from'->'hardSwitches') = 'object' AND NOT ("change"->'from'->'hardSwitches' ? 'changeProjectSettings');--> statement-breakpoint
UPDATE "proposals" SET "change" = jsonb_set("change", '{to,hardSwitches,changeProjectSettings}', CASE "change"->>'roleKey' WHEN 'devops' THEN '{"kind":"allowed"}'::jsonb WHEN 'developer' THEN '{"kind":"consult","role":"devops"}'::jsonb WHEN 'cto' THEN '{"kind":"consult","role":"devops"}'::jsonb WHEN 'planner' THEN '{"kind":"never"}'::jsonb WHEN 'reviewer' THEN '{"kind":"never"}'::jsonb WHEN 'office-manager' THEN '{"kind":"never"}'::jsonb WHEN 'caretaker' THEN '{"kind":"never"}'::jsonb ELSE '{"kind":"ask-me"}'::jsonb END) WHERE "change"->>'kind' = 'change' AND jsonb_typeof("change"->'to'->'hardSwitches') = 'object' AND NOT ("change"->'to'->'hardSwitches' ? 'changeProjectSettings');
